const c = await api.get("/customers", { status: "delayed" });
const m = await api.get("/mails", { label: "complaint" });
const delayedIds = new Set(c.items.map(x => x.id));
const complaintCustIds = m.items.map(x => x.customer_id);
const result = [...new Set(complaintCustIds.filter(id => delayedIds.has(id)))];
return { delayed_customer_ids: [...delayedIds], complaint_mail_customer_ids: complaintCustIds, both: result };

